#include <stdio.h>
#include <stdlib.h>

int minStartValue(int* nums, int numsSize) {
    int prefix = 0;
    int minPrefix = 0;

    for (int i = 0; i < numsSize; ++i) {
        prefix += nums[i];
        if (prefix < minPrefix) {
            minPrefix = prefix;
        }
    }

    return 1 - minPrefix;
}

